import java.util.*;
import java.io.*;

public class Main {
    static long[] processQueries(long[] capacities, long[][] queries) {
        // Write your solution here
        return new long[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] capacities = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            capacities[i] = (long) in.nval;
        }
        in.nextToken();
        int q = (int) in.nval;
        long[][] queries = new long[q][];
        for (int i = 0; i < q; i++) {
            in.nextToken();
            long t = (long) in.nval;
            if (t == 3) {
                in.nextToken();
                long a = (long) in.nval;
                in.nextToken();
                long b = (long) in.nval;
                queries[i] = new long[]{3, a, b};
            } else {
                in.nextToken();
                queries[i] = new long[]{t, (long) in.nval};
            }
        }
        long[] res = processQueries(capacities, queries);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "");
        System.out.println(sb);
    }
}
